create or replace function public.get_creator_profile(profile_id uuid) returns jsonb language sql stable security invoker set search_path='' as $$
select jsonb_build_object('id',p.id,'name',coalesce(p.display_name,p.business_name),'business_name',p.business_name,'bio',coalesce(p.bio,''),'location',coalesce(p.location,p.business_address,'Accra'),'verified',p.is_verified,'avatar',p.profile_photo_url,'cover',coalesce(p.cover_image_url,(select image_url from public.feed_posts where professional_id=p.id and is_published order by created_at desc limit 1)),'years',coalesce(p.years_experience,0),'followers',(select count(*) from public.professional_follows f where f.professional_id=p.id),'following',exists(select 1 from public.professional_follows f where f.professional_id=p.id and f.user_id=(select auth.uid())),'bookings',(select count(*) from public.bookings b where b.professional_id=p.id and b.status='completed'),'rating',coalesce((select avg(rating) from public.feed_posts where professional_id=p.id and rating_count>0),0),'review_count',coalesce((select max(rating_count) from public.feed_posts where professional_id=p.id),0),'category',coalesce((select i.name from public.professional_services s join public.interests i on i.id=s.interest_id where s.professional_id=p.id and s.is_active order by s.sort_order,s.created_at limit 1),'Beauty'),'portfolio',coalesce((select jsonb_agg(jsonb_build_object('id',fp.id,'image',fp.image_url,'caption',fp.caption,'aspect_ratio',fp.aspect_ratio) order by fp.created_at desc) from public.feed_posts fp where fp.professional_id=p.id and fp.is_published),'[]'::jsonb)) from public.professional_profiles p where p.id=profile_id;
$$;
grant execute on function public.get_creator_profile(uuid) to anon,authenticated;
